// 1. Extracción profunda y específica para Gemini 3.1 Flash Lite
let rawData = $input.item.json;
let textToParse = "";

// Buscamos la ruta exacta donde Gemini 3.1 esconde el texto
if (rawData.content && rawData.content.parts && rawData.content.parts[0] && rawData.content.parts[0].text) {
    textToParse = rawData.content.parts[0].text;
} else if (rawData.message && rawData.message.content) {
    textToParse = rawData.message.content;
} else if (rawData.text) {
    textToParse = rawData.text;
} else {
    textToParse = JSON.stringify(rawData);
}

// 2. Forzar conversión a String
textToParse = String(textToParse);

// 3. Extracción Blindada con Regex
const match = textToParse.match(/\{[\s\S]*\}/);
let extractedJson = match ? match[0] : textToParse;

// 4. Parseo y salida
try {
    const parsedData = JSON.parse(extractedJson);
    return { json: parsedData };
} catch (error) {
    return {
        json: {
            "Moral": "Error de Parseo",
            "Legalidad": "Error de Parseo",
            "Indiferencia": "Error de Parseo",
            "Corrupto": "Error de Parseo",
            "Economico": "Error de Parseo",
            "Politico": "Error de Parseo",
            "Social": "Error de Parseo",
            "Religioso": "Error de Parseo",
            "Tendencia_Valores": "Error de Parseo",
            "Tendencia_Intereses": "Error de Parseo"
        }
    };
}
